type _DaemonIdentityRegistration = tuple[str, str, str, str]


def _require_daemon_identity_registration(
    candidate: object,
    *,
    _context_pattern: re.Pattern[str] = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,255}"),
    _daemon_pattern: re.Pattern[str] = re.compile(r"[A-Za-z0-9][A-Za-z0-9:._-]{0,255}"),
    _normpath: Callable[[str], str] = os.path.normpath,
) -> _DaemonIdentityRegistration:
    if (
        type(candidate) is not tuple
        or len(candidate) != 4
        or tuple.__getitem__(candidate, 0) != "trusted-time-daemon-identity-registration-v1"
        or type(tuple.__getitem__(candidate, 1)) is not str
        or type(tuple.__getitem__(candidate, 2)) is not str
        or type(tuple.__getitem__(candidate, 3)) is not str
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation session is invalid"
        )
    exact = cast(_DaemonIdentityRegistration, candidate)
    context_name = tuple.__getitem__(exact, 1)
    endpoint = tuple.__getitem__(exact, 2)
    daemon_id = tuple.__getitem__(exact, 3)
    socket_path = endpoint[7:] if endpoint.startswith("unix://") else ""
    if (
        (context_name != "<DOCKER_HOST>" and _context_pattern.fullmatch(context_name) is None)
        or _daemon_pattern.fullmatch(daemon_id) is None
        or not endpoint
        or len(endpoint) > 4_096
        or any(ord(character) < 32 or ord(character) == 127 for character in endpoint)
        or not endpoint.startswith("unix:///")
        or "%" in endpoint
        or "?" in endpoint
        or "#" in endpoint
        or not socket_path.startswith("/")
        or socket_path.startswith("//")
        or "//" in socket_path
        or _normpath(socket_path) != socket_path
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation session is invalid"
        )
    return exact


def _capture_daemon_identity_registration(
    candidate: object,
    *,
    _identity_type: type[LocalDockerDaemonIdentity] = LocalDockerDaemonIdentity,
    _require_registration: Callable[[object], _DaemonIdentityRegistration] = (
        _require_daemon_identity_registration
    ),
) -> _DaemonIdentityRegistration:
    """Capture the caller-selected daemon descriptor exactly once at entry."""

    try:
        if type(candidate) is not _identity_type:
            raise ValueError
        selected = candidate
        return _require_registration(
            (
                "trusted-time-daemon-identity-registration-v1",
                selected.context_name,
                selected.endpoint,
                selected.daemon_id,
            )
        )
    except BaseException as error:
        if not isinstance(error, Exception):
            raise
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation session is invalid"
        ) from None


def _daemon_identity_view(
    registration: object,
    *,
    _identity_type: type[LocalDockerDaemonIdentity] = LocalDockerDaemonIdentity,
    _require_registration: Callable[[object], _DaemonIdentityRegistration] = (
        _require_daemon_identity_registration
    ),
) -> LocalDockerDaemonIdentity:
    exact = _require_registration(registration)
    return _identity_type(
        context_name=tuple.__getitem__(exact, 1),
        endpoint=tuple.__getitem__(exact, 2),
        daemon_id=tuple.__getitem__(exact, 3),
    )


def _environment_identity_sha256(
    payload: tuple[tuple[str, str], ...],
    *,
    _serialize: Callable[[object], bytes] = _EXACT_IMMUTABLE_JSON_SERIALIZER,
    _sha256: Callable[[bytes], Any] = hashlib.sha256,
    _ordered_keys: tuple[str, ...] = (
        "DOCKER_HOST",
        "LANG",
        "LC_ALL",
        "NO_COLOR",
        "PATH",
        "TERM",
        "TMPDIR",
    ),
) -> str:
    keys = tuple(tuple.__getitem__(item, 0) for item in payload) if type(payload) is tuple else ()
    if (
        type(payload) is not tuple
        or any(
            type(item) is not tuple
            or len(item) != 2
            or type(tuple.__getitem__(item, 0)) is not str
            or type(tuple.__getitem__(item, 1)) is not str
            for item in payload
        )
        or len(keys) != len(frozenset(keys))
        or keys != tuple(key for key in _ordered_keys if key in keys)
        or not keys
        or tuple.__getitem__(keys, 0) != "DOCKER_HOST"
        or "PATH" not in keys
    ):
        raise ValueError
    return cast(str, _sha256(_serialize((0, payload))).hexdigest())


