    def sealed_live_claim_projection(
        candidate: object,
    ) -> tuple[str, str, str, bytes] | None:
        values = sealed_projection_descriptor_values(
            candidate,
            sealed_start_claim_type,
            _sealed_start_claim_descriptors,
        )
        if values is None:
            return None
        approval = sealed_live_approval_projection(_exact_tuple_getitem(values, 0))
        if approval is None:
            return None
        approval_projection = sealed_approval_projection(approval)
        if approval_projection is None:
            return None
        confirmed = sealed_json_object_get(approval, "confirmed_enrollment")
        reauthentication = sealed_live_reauthentication_projection(
            _exact_tuple_getitem(values, 1),
            approval_projection,
            confirmed,
        )
        if reauthentication is None:
            return None
        approval_sha256 = sealed_sha256_bytes(sealed_json_object_bytes(approval))
        reauthentication_sha256 = sealed_sha256_bytes(sealed_json_object_bytes(reauthentication))
        if approval_sha256 is None or reauthentication_sha256 is None:
            return None
        operation_id = _exact_tuple_getitem(approval_projection, 0)
        entries: tuple[tuple[str, object], ...] = ()
        for field_name in authority_field_names + claim_closed_field_names:
            entries += ((field_name, False),)
        entries += (
            ("approval", approval),
            ("approval_sha256", approval_sha256),
            (
                "claim_contract_version",
                "phase6d-post-enrollment-start-single-use-claim-v1",
            ),
            ("operation_id", operation_id),
            ("reauthentication", reauthentication),
            ("reauthentication_sha256", reauthentication_sha256),
            ("service", "trusted-time-post-enrollment-start"),
            ("status", "claim_projection_not_retained"),
        )
        projection = sealed_projection_object(entries)
        projection_bytes = sealed_json_object_bytes(projection)
        claim_sha256 = sealed_sha256_bytes(projection_bytes)
        if claim_sha256 is None:
            return None
        return operation_id, approval_sha256, claim_sha256, projection_bytes

    def sealed_claim_semantic_projection(
        encoded: object,
    ) -> tuple[str, str, str, bytes] | None:
        try:
            payload = decode_canonical_json_object(encoded, maximum_bytes=32_768)
            retained_keys = _exact_tuple(
                _exact_sorted(
                    authority_field_names
                    + claim_closed_field_names
                    + (
                        "claim",
                        "claim_projection_sha256",
                        "contract_version",
                        "operation_id",
                        "service",
                        "status",
                    )
                )
            )
            if (
                sealed_json_object_keys(payload) != retained_keys
                or not sealed_false_fields(payload, authority_field_names)
                or not sealed_false_fields(payload, claim_closed_field_names)
                or sealed_json_object_get(payload, "contract_version")
                != "phase6d-post-enrollment-start-retained-claim-v1"
                or sealed_json_object_get(payload, "service")
                != "trusted-time-post-enrollment-start-host-launcher"
                or sealed_json_object_get(payload, "status") != "claim_persistence_payload"
            ):
                return None
            operation_id = sealed_json_object_get(payload, "operation_id")
            claim_projection_sha256 = sealed_json_object_get(
                payload,
                "claim_projection_sha256",
            )
            claim_payload = sealed_json_object_get(payload, "claim")
            claim_keys = _exact_tuple(
                _exact_sorted(
                    authority_field_names
                    + claim_closed_field_names
                    + (
                        "approval",
                        "approval_sha256",
                        "claim_contract_version",
                        "operation_id",
                        "reauthentication",
                        "reauthentication_sha256",
                        "service",
                        "status",
                    )
                )
            )
            if (
                sealed_json_object_keys(claim_payload) != claim_keys
                or not sealed_false_fields(claim_payload, authority_field_names)
                or not sealed_false_fields(claim_payload, claim_closed_field_names)
                or sealed_json_object_get(claim_payload, "claim_contract_version")
                != "phase6d-post-enrollment-start-single-use-claim-v1"
                or sealed_json_object_get(claim_payload, "service")
                != "trusted-time-post-enrollment-start"
                or sealed_json_object_get(claim_payload, "status")
                != "claim_projection_not_retained"
                or sealed_json_object_get(claim_payload, "operation_id") != operation_id
                or not sealed_uuid4_text(operation_id)
                or not sealed_sha256_text(claim_projection_sha256)
                or sealed_sha256_bytes(sealed_json_object_bytes(claim_payload))
                != claim_projection_sha256
            ):
                return None
            approval = sealed_json_object_get(claim_payload, "approval")
            reauthentication = sealed_json_object_get(claim_payload, "reauthentication")
            approval_sha256 = sealed_json_object_get(claim_payload, "approval_sha256")
            reauthentication_sha256 = sealed_json_object_get(
                claim_payload,
                "reauthentication_sha256",
            )
            approval_projection = sealed_approval_projection(approval)
            confirmed = sealed_json_object_get(approval, "confirmed_enrollment")
            if (
                approval_projection is None
                or not sealed_sha256_text(approval_sha256)
                or not sealed_sha256_text(reauthentication_sha256)
                or sealed_sha256_bytes(sealed_json_object_bytes(approval)) != approval_sha256
                or sealed_sha256_bytes(sealed_json_object_bytes(reauthentication))
                != reauthentication_sha256
                or not sealed_reauthentication_projection(
                    reauthentication,
                    approval_projection,
                    confirmed,
                )
                or _exact_tuple_getitem(approval_projection, 0) != operation_id
                or _exact_tuple_getitem(approval_projection, 1) != approval_sha256
                or sealed_json_object_get(approval, "operation_id") != operation_id
                or sealed_json_object_get(reauthentication, "operation_id") != operation_id
                or sealed_json_object_get(reauthentication, "approval_sha256") != approval_sha256
                or sealed_json_object_get(approval, "contract_version")
                != "phase6d-post-enrollment-start-exact-operation-approval-v1"
                or sealed_json_object_get(approval, "service")
                != "trusted-time-post-enrollment-start"
                or sealed_json_object_get(approval, "status")
                != "approval_projection_external_attestation_required"
                or sealed_json_object_get(reauthentication, "contract_version")
                != "phase6d-post-enrollment-start-runtime-reauthentication-v1"
                or sealed_json_object_get(reauthentication, "service")
                != "trusted-time-post-enrollment-start"
                or sealed_json_object_get(reauthentication, "status")
                != "runtime_reauthentication_projection_unsealed"
            ):
                return None
            return (
                operation_id,  # type: ignore[return-value]
                approval_sha256,
                claim_projection_sha256,
                sealed_json_object_bytes(claim_payload),
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None

    def sealed_retained_claim_object_projection(
        retained: object,
    ) -> tuple[object, ...] | None:
        if (
            not controller_projection_types_finalized
            or _exact_type(retained) is not sealed_retained_claim_type
        ):
            return None
        try:
            claim_object = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 0),
                retained,
                sealed_retained_claim_type,
            )
            operation_id = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 1),
                retained,
                sealed_retained_claim_type,
            )
            claim_projection_sha256 = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 2),
                retained,
                sealed_retained_claim_type,
            )
            artifact_sha256 = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 3),
                retained,
                sealed_retained_claim_type,
            )
            artifact_path = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 4),
                retained,
                sealed_retained_claim_type,
            )
            encoded = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 5),
                retained,
                sealed_retained_claim_type,
            )
            file_identity = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 6),
                retained,
                sealed_retained_claim_type,
            )
            path_snapshot = sealed_path_snapshot(artifact_path)
            semantic = sealed_claim_semantic_projection(encoded)
            live_claim_before = sealed_live_claim_projection(claim_object)
            claim_object_after = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 0),
                retained,
                sealed_retained_claim_type,
            )
            live_claim_after = sealed_live_claim_projection(claim_object)
            if (
                _exact_type(claim_object) is not sealed_start_claim_type
                or claim_object_after is not claim_object
                or not sealed_uuid4_text(operation_id)
                or not sealed_sha256_text(claim_projection_sha256)
                or not sealed_sha256_text(artifact_sha256)
                or path_snapshot is None
                or _exact_type(encoded) is not _exact_bytes_type
                or not encoded
                or _exact_len(encoded) > 32_768
                or sealed_stat_identity(
                    file_identity,
                    kind="regular",
                    expected_size=_exact_len(encoded),
                )
                is None
                or sealed_sha256_bytes(encoded) != artifact_sha256
                or semantic is None
                or live_claim_before is None
                or live_claim_after != live_claim_before
                or _exact_tuple_getitem(semantic, 0) != operation_id
                or _exact_tuple_getitem(semantic, 2) != claim_projection_sha256
                or semantic != live_claim_before
            ):
                return None
            path_value = _exact_tuple_getitem(path_snapshot, 0)
            material = (
                "trusted-time-sealed-json-object-v1",
                (
                    ("artifact_path", path_value),
                    ("artifact_sha256", artifact_sha256),
                    ("claim_projection_sha256", claim_projection_sha256),
                    ("encoded_sha256", artifact_sha256),
                    ("encoded_size", _exact_len(encoded)),
                    (
                        "file_identity",
                        ("trusted-time-sealed-json-array-v1", file_identity),
                    ),
                    ("operation_id", operation_id),
                ),
            )
            binding_sha256 = sealed_sha256_bytes(sealed_json_object_bytes(material))
            if binding_sha256 is None:
                return None
            return (
                operation_id,
                claim_projection_sha256,
                artifact_sha256,
                path_value,
                encoded,
                file_identity,
                _exact_tuple_getitem(semantic, 0),
                _exact_tuple_getitem(semantic, 1),
                _exact_tuple_getitem(semantic, 2),
                binding_sha256,
                _exact_tuple_getitem(semantic, 3),
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None

    def sealed_retained_claim_references_claim(
        retained: object,
        claim: object,
    ) -> bool:
        if (
            not controller_projection_types_finalized
            or _exact_type(retained) is not sealed_retained_claim_type
            or _exact_type(claim) is not sealed_start_claim_type
        ):
            return False
        try:
            return (
                sealed_descriptor_value(
                    _exact_tuple_getitem(sealed_retained_claim_descriptors, 0),
                    retained,
                    sealed_retained_claim_type,
                )
                is claim
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return False

    def sealed_claim_artifact_material(
        claim: object,
        artifact_directory: object,
        ignored_root: object,
        *,
        builtin_roots: bool,
        expected_encoded: object,
        expected_file_identity: object,
    ) -> tuple[bytes, tuple[int, ...], tuple[str, str, tuple[str, ...]]] | None:
        live_claim_before = sealed_live_claim_projection(claim)
        roots = (
            sealed_builtin_roots(artifact_directory, ignored_root)
            if builtin_roots
            else sealed_public_roots(artifact_directory, ignored_root)
        )
        if live_claim_before is None or roots is None:
            return None
        ignored_value = _exact_tuple_getitem(roots, 1)
        artifact_components = _exact_tuple_getitem(roots, 2)
        directory_owners: tuple[_NativeOwnedFileDescriptor, ...] = ()
        root_candidate: _NativeOwnedFileDescriptor | None = None
        child_candidate: _NativeOwnedFileDescriptor | None = None
        primary_error: BaseException | None = None
        cleanup_error: BaseException | None = None
        result: (
            tuple[
                bytes,
                tuple[int, ...],
                tuple[str, str, tuple[str, ...]],
            ]
            | None
        ) = None
        body_completed = False
        cleanup_completed = False

        def remember_claim_material_cleanup_error(error: BaseException) -> None:
            nonlocal cleanup_error
            if cleanup_error is None or (
                _exact_isinstance(cleanup_error, _ordinary_exception_type)
                and not _exact_isinstance(error, _ordinary_exception_type)
            ):
                cleanup_error = error

        def finish_claim_material_cleanup_once() -> None:
            nonlocal cleanup_completed
            try:
                owners: tuple[object | None, ...] = (
                    *directory_owners,
                    root_candidate,
                    child_candidate,
                )
                close_sealed_native_owners_once(owners)
                if sealed_native_owners_are_closed(owners):
                    cleanup_completed = True
            except _base_exception_type as error:
                remember_claim_material_cleanup_error(error)

        try:
            try:
                root_candidate = _native_open_root()
                directory_owners += (root_candidate,)
                root_candidate = None
                current_value = "/"
                for component in artifact_components:
                    parent_owner = _exact_tuple_getitem(directory_owners, -1)
                    child_candidate = _native_open_directory(parent_owner, component)
                    directory_owners += (child_candidate,)
                    child_owner = child_candidate
                    child_candidate = None
                    child_identity = sealed_stat_identity(
                        _native_owner_fstat(child_owner),
                        kind="directory",
                        expected_size=None,
                    )
                    current_value = (
                        current_value + component
                        if current_value == "/"
                        else current_value + "/" + component
                    )
                    protected = current_value == ignored_value or _str_startswith(
                        current_value,
                        ignored_value + ("" if ignored_value == "/" else "/"),
                    )
                    if child_identity is None or (
                        protected
                        and (
                            _exact_tuple_getitem(child_identity, 3) != _effective_uid
                            or _exact_tuple_getitem(child_identity, 2) & 0o7777 != 0o700
                        )
                    ):
                        raise sealed_reader_error(
                            "trusted-time retained claim directory is unavailable"
                        )
                directory_owner = _exact_tuple_getitem(directory_owners, -1)
                for index in _exact_range(_exact_len(artifact_components)):
                    parent_owner = _exact_tuple_getitem(directory_owners, index)
                    child_owner = _exact_tuple_getitem(directory_owners, index + 1)
                    if _native_owner_statat(
                        parent_owner,
                        _exact_tuple_getitem(artifact_components, index),
                    ) != _native_owner_fstat(child_owner):
                        raise sealed_reader_error("trusted-time retained claim path changed")
                initial_inventory = sealed_inventory_snapshot(directory_owner)
                observed = sealed_read_regular(
                    directory_owner,
                    "trusted-time-post-enrollment-start-claim.json",
                    32_768,
                )
                if initial_inventory is None or observed is None:
                    raise sealed_reader_error("trusted-time retained claim is unavailable")
                encoded = _exact_tuple_getitem(observed, 0)
                file_identity = _exact_tuple_getitem(observed, 1)
                semantic = sealed_claim_semantic_projection(encoded)
                names = _exact_tuple_getitem(initial_inventory, 0)
                filtered: tuple[str, ...] = ()
                for name in names:
                    if name == "trusted-time-post-enrollment-start-claim.json" or (
                        _str_startswith(name, "trusted-time-post-enrollment-start-claim-")
                        and _str_endswith(name, ".json")
                    ):
                        filtered += (name,)
                if (
                    filtered != ("trusted-time-post-enrollment-start-claim.json",)
                    or semantic != live_claim_before
                    or (expected_encoded is not None and encoded != expected_encoded)
                    or (
                        expected_file_identity is not None
                        and file_identity != expected_file_identity
                    )
                    or _native_owner_statat(
                        directory_owner,
                        "trusted-time-post-enrollment-start-claim.json",
                    )
                    != file_identity
                ):
                    raise sealed_reader_error("trusted-time retained claim is unavailable")
                _native_owner_fsync(directory_owner)
                final_inventory = sealed_inventory_snapshot(directory_owner)
                live_claim_after = sealed_live_claim_projection(claim)
                roots_after = (
                    sealed_builtin_roots(artifact_directory, ignored_root)
                    if builtin_roots
                    else sealed_public_roots(artifact_directory, ignored_root)
                )
                for index in _exact_range(_exact_len(artifact_components)):
                    parent_owner = _exact_tuple_getitem(directory_owners, index)
                    child_owner = _exact_tuple_getitem(directory_owners, index + 1)
                    if _native_owner_statat(
                        parent_owner,
                        _exact_tuple_getitem(artifact_components, index),
                    ) != _native_owner_fstat(child_owner):
                        raise sealed_reader_error("trusted-time retained claim path changed")
                if (
                    final_inventory != initial_inventory
                    or live_claim_after != live_claim_before
                    or roots_after != roots
                    or _native_owner_statat(
                        directory_owner,
                        "trusted-time-post-enrollment-start-claim.json",
                    )
                    != file_identity
                ):
                    raise sealed_reader_error("trusted-time retained claim changed")
                result = encoded, file_identity, roots
                body_completed = True
            except _base_exception_type as error:
                primary_error = error
        finally:
            try:
                finish_claim_material_cleanup_once()
            finally:
                try:
                    if not cleanup_completed:
                        finish_claim_material_cleanup_once()
                finally:
                    try:
                        if not cleanup_completed:
                            finish_claim_material_cleanup_once()
                    finally:
                        if not cleanup_completed:
                            finish_claim_material_cleanup_once()
            if not cleanup_completed and cleanup_error is None:
                cleanup_error = sealed_reader_error(
                    "trusted-time projection native owner cleanup is unavailable"
                )
        terminal = primary_error
        if terminal is None or (
            _exact_isinstance(terminal, _ordinary_exception_type)
            and cleanup_error is not None
            and not _exact_isinstance(cleanup_error, _ordinary_exception_type)
        ):
            terminal = cleanup_error
        if terminal is not None:
            if not _exact_isinstance(terminal, _ordinary_exception_type):
                raise terminal
            return None
        return result if body_completed else None

    def sealed_retained_claim_durable_projection(
        retained: object,
        artifact_directory: object,
        ignored_root: object,
        *,
        builtin_roots: bool = False,
    ) -> tuple[object, ...] | None:
        before = sealed_retained_claim_object_projection(retained)
        if before is None:
            return None
        try:
            claim = sealed_descriptor_value(
                _exact_tuple_getitem(sealed_retained_claim_descriptors, 0),
                retained,
                sealed_retained_claim_type,
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None
        material = sealed_claim_artifact_material(
            claim,
            artifact_directory,
            ignored_root,
            builtin_roots=builtin_roots,
            expected_encoded=_exact_tuple_getitem(before, 4),
            expected_file_identity=_exact_tuple_getitem(before, 5),
        )
        after = sealed_retained_claim_object_projection(retained)
        if material is None or after != before:
            return None
        roots = _exact_tuple_getitem(material, 2)
        artifact_value = _exact_tuple_getitem(roots, 0)
        if _exact_tuple_getitem(before, 3) != (
            artifact_value + "/trusted-time-post-enrollment-start-claim.json"
        ):
            return None
        return before

    def sealed_rehydrate_retained_claim(
        claim: object,
        *,
        artifact_directory: object,
        ignored_root: object,
    ) -> object | None:
        material = sealed_claim_artifact_material(
            claim,
            artifact_directory,
            ignored_root,
            builtin_roots=False,
            expected_encoded=None,
            expected_file_identity=None,
        )
        if material is None:
            return None
        encoded = _exact_tuple_getitem(material, 0)
        file_identity = _exact_tuple_getitem(material, 1)
        roots = _exact_tuple_getitem(material, 2)
        artifact_value = _exact_tuple_getitem(roots, 0)
        artifact_path_value = artifact_value + "/trusted-time-post-enrollment-start-claim.json"
        semantic = sealed_claim_semantic_projection(encoded)
        artifact_sha256 = sealed_sha256_bytes(encoded)
        if semantic is None or artifact_sha256 is None:
            return None
        try:
            artifact_path = _object_new(_path_concrete_type)
            _member_descriptor_set(
                _path_raw_paths_descriptor,
                artifact_path,
                [artifact_path_value],
            )
            _member_descriptor_set(
                _path_str_descriptor,
                artifact_path,
                artifact_path_value,
            )
            if sealed_path_snapshot(artifact_path) is None:
                return None
            retained = _object_new(sealed_retained_claim_type)
            retained_values = (
                claim,
                _exact_tuple_getitem(semantic, 0),
                _exact_tuple_getitem(semantic, 2),
                artifact_sha256,
                artifact_path,
                encoded,
                file_identity,
            )
            for index in _exact_range(_exact_len(sealed_retained_claim_descriptors)):
                _member_descriptor_set(
                    _exact_tuple_getitem(sealed_retained_claim_descriptors, index),
                    retained,
                    _exact_tuple_getitem(retained_values, index),
                )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None
        projection = sealed_retained_claim_object_projection(retained)
        if (
            projection is None
            or _exact_tuple_getitem(projection, 4) != encoded
            or _exact_tuple_getitem(projection, 5) != file_identity
            or _exact_tuple_getitem(projection, 10) != _exact_tuple_getitem(semantic, 3)
        ):
            return None
        return retained

    recovery_closed_field_names = (
        "authority_granted",
        "claim_chronology_authenticated",
        "claim_retention_authorized",
        "database_secret_disclosed",
        "outcome_retention_authorized",
        "persistent_start_authorized",
        "persistent_start_confirmed",
        "qualified",
        "release_attempted",
        "release_authorized",
        "release_confirmed",
        "retry_authorized",
        "sequence_2_authorized",
        "sequence_2_confirmed",
        "shutdown_authorized",
        "source_start_authorized",
        "supervisor_start_authorized",
        "topology_mutation_authorized",
        "topology_qualified",
    )

    def sealed_recovery_semantic_projection(
        encoded: object,
    ) -> tuple[str, str, str, str] | None:
        try:
            payload = decode_canonical_json_object(encoded, maximum_bytes=128 * 1_024)
            fields = (
                authority_field_names
                + recovery_closed_field_names
                + (
                    "approval_sha256",
                    "claim_retention_revalidated",
                    "claim_sha256",
                    "contract_version",
                    "operation_id",
                    "reason",
                    "retained_claim_artifact_sha256",
                    "service",
                    "status",
                )
            )
            operation_id = sealed_json_object_get(payload, "operation_id")
            approval_sha256 = sealed_json_object_get(payload, "approval_sha256")
            claim_sha256 = sealed_json_object_get(payload, "claim_sha256")
            artifact_sha256 = sealed_json_object_get(
                payload,
                "retained_claim_artifact_sha256",
            )
            if (
                not sealed_object_has_keys(payload, fields)
                or not sealed_false_fields(payload, authority_field_names)
                or not sealed_false_fields(payload, recovery_closed_field_names)
                or not sealed_uuid4_text(operation_id)
                or not sealed_sha256_text(approval_sha256)
                or not sealed_sha256_text(claim_sha256)
                or not sealed_sha256_text(artifact_sha256)
                or sealed_json_object_get(payload, "claim_retention_revalidated") is not True
                or sealed_json_object_get(payload, "contract_version")
                != "phase6d-post-enrollment-start-retained-recovery-outcome-v1"
                or sealed_json_object_get(payload, "service")
                != "trusted-time-post-enrollment-start-host-controller"
                or sealed_json_object_get(payload, "status") != "recovery_required"
                or sealed_json_object_get(payload, "reason")
                != "post_enrollment_start_recovery_required"
            ):
                return None
            return (  # type: ignore[return-value]
                operation_id,
                approval_sha256,
                claim_sha256,
                artifact_sha256,
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None

    def sealed_recovery_receipt_object_projection(
        receipt: object,
    ) -> tuple[object, ...] | None:
        if (
            not controller_projection_types_finalized
            or recovery_receipt_projection_type is None
            or recovery_receipt_projection_descriptors is None
            or recovery_status_projection_member is None
            or recovery_reason_projection_member is None
            or _exact_type(receipt) is not recovery_receipt_projection_type
        ):
            return None
        try:
            values: tuple[object, ...] = ()
            for descriptor in recovery_receipt_projection_descriptors:
                values += (
                    sealed_descriptor_value(
                        descriptor,
                        receipt,
                        recovery_receipt_projection_type,
                    ),
                )
            operation_id = _exact_tuple_getitem(values, 0)
            approval_sha256 = _exact_tuple_getitem(values, 1)
            claim_sha256 = _exact_tuple_getitem(values, 2)
            retained_claim_artifact_sha256 = _exact_tuple_getitem(values, 3)
            outcome_sha256 = _exact_tuple_getitem(values, 4)
            artifact_path = _exact_tuple_getitem(values, 5)
            encoded = _exact_tuple_getitem(values, 6)
            file_identity = _exact_tuple_getitem(values, 7)
            slot_file_identity = _exact_tuple_getitem(values, 8)
            status = _exact_tuple_getitem(values, 9)
            reason = _exact_tuple_getitem(values, 10)
            path_snapshot = sealed_path_snapshot(artifact_path)
            semantic = sealed_recovery_semantic_projection(encoded)
            if (
                not sealed_uuid4_text(operation_id)
                or not sealed_sha256_text(approval_sha256)
                or not sealed_sha256_text(claim_sha256)
                or not sealed_sha256_text(retained_claim_artifact_sha256)
                or not sealed_sha256_text(outcome_sha256)
                or path_snapshot is None
                or _exact_type(encoded) is not _exact_bytes_type
                or not encoded
                or _exact_len(encoded) > 128 * 1_024
                or sealed_sha256_bytes(encoded) != outcome_sha256
                or sealed_stat_identity(
                    file_identity,
                    kind="regular",
                    expected_size=_exact_len(encoded),
                )
                is None
                or sealed_stat_identity(
                    slot_file_identity,
                    kind="regular",
                    expected_size=None,
                )
                is None
                or status is not recovery_status_projection_member
                or reason is not recovery_reason_projection_member
                or semantic is None
                or semantic
                != (
                    operation_id,
                    approval_sha256,
                    claim_sha256,
                    retained_claim_artifact_sha256,
                )
            ):
                return None
            path_value = _exact_tuple_getitem(path_snapshot, 0)
            path_components = _exact_tuple_getitem(path_snapshot, 2)
            if not path_components or _exact_tuple_getitem(
                path_components, _exact_len(path_components) - 1
            ) != ("trusted-time-post-enrollment-start-outcome-" + outcome_sha256 + ".json"):
                return None
            return (
                operation_id,
                approval_sha256,
                claim_sha256,
                retained_claim_artifact_sha256,
                outcome_sha256,
                path_value,
                encoded,
                file_identity,
                slot_file_identity,
                "recovery_required",
                "post_enrollment_start_recovery_required",
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None

    def sealed_outcome_slot_bytes(
        contract_version: str,
        outcome_sha256: str,
        status: str,
    ) -> bytes:
        return sealed_json_object_bytes(
            (
                "trusted-time-sealed-json-object-v1",
                (
                    ("contract_version", contract_version),
                    ("outcome_sha256", outcome_sha256),
                    ("status", status),
                ),
            )
        )

    def sealed_read_open_owner(
        owner: _NativeOwnedFileDescriptor,
        maximum_bytes: int,
    ) -> tuple[bytes, tuple[int, ...]] | None:
        _native_owner_fsync(owner)
        encoded, before, after = _native_owner_read(owner, maximum_bytes)
        final = _native_owner_fstat(owner)
        identity = sealed_stat_identity(
            before,
            kind="regular",
            expected_size=_exact_len(encoded),
        )
        if (
            _exact_type(encoded) is not _exact_bytes_type
            or identity is None
            or after != before
            or final != before
        ):
            return None
        return encoded, identity

    def sealed_recovery_durable_projection(
        receipt: object,
        artifact_directory: object,
        ignored_root: object,
        *,
        builtin_roots: bool = False,
    ) -> tuple[object, ...] | None:
        before = sealed_recovery_receipt_object_projection(receipt)
        roots = (
            sealed_builtin_roots(artifact_directory, ignored_root)
            if builtin_roots
            else sealed_public_roots(artifact_directory, ignored_root)
        )
        if before is None or roots is None:
            return None
        artifact_value = _exact_tuple_getitem(roots, 0)
        ignored_value = _exact_tuple_getitem(roots, 1)
        artifact_components = _exact_tuple_getitem(roots, 2)
        outcome_sha256 = _exact_tuple_getitem(before, 4)
        outcome_file_name = "trusted-time-post-enrollment-start-outcome-" + outcome_sha256 + ".json"
        if _exact_tuple_getitem(before, 5) != artifact_value + "/" + outcome_file_name:
            return None
        directory_owners: tuple[_NativeOwnedFileDescriptor, ...] = ()
        root_candidate: _NativeOwnedFileDescriptor | None = None
        child_candidate: _NativeOwnedFileDescriptor | None = None
        slot_candidate: _NativeOwnedFileDescriptor | None = None
        slot_owner: _NativeOwnedFileDescriptor | None = None
        primary_error: BaseException | None = None
        cleanup_error: BaseException | None = None
        durable = False
        cleanup_completed = False

        def remember_recovery_cleanup_error(error: BaseException) -> None:
            nonlocal cleanup_error
            if cleanup_error is None or (
                _exact_isinstance(cleanup_error, _ordinary_exception_type)
                and not _exact_isinstance(error, _ordinary_exception_type)
            ):
                cleanup_error = error

        def finish_recovery_cleanup_once() -> None:
            nonlocal cleanup_completed
            try:
                owners: tuple[object | None, ...] = (
                    *directory_owners,
                    root_candidate,
                    child_candidate,
                    slot_candidate,
                    slot_owner,
                )
                close_sealed_native_owners_once(owners)
                if sealed_native_owners_are_closed(owners):
                    cleanup_completed = True
            except _base_exception_type as error:
                remember_recovery_cleanup_error(error)

        try:
            try:
                root_candidate = _native_open_root()
                directory_owners += (root_candidate,)
                root_candidate = None
                current_value = "/"
                for component in artifact_components:
                    parent_owner = _exact_tuple_getitem(directory_owners, -1)
                    child_candidate = _native_open_directory(parent_owner, component)
                    directory_owners += (child_candidate,)
                    child_owner = child_candidate
                    child_candidate = None
                    child_identity = sealed_stat_identity(
                        _native_owner_fstat(child_owner),
                        kind="directory",
                        expected_size=None,
                    )
                    current_value = (
                        current_value + component
                        if current_value == "/"
                        else current_value + "/" + component
                    )
                    protected = current_value == ignored_value or _str_startswith(
                        current_value,
                        ignored_value + ("" if ignored_value == "/" else "/"),
                    )
                    if child_identity is None or (
                        protected
                        and (
                            _exact_tuple_getitem(child_identity, 3) != _effective_uid
                            or _exact_tuple_getitem(child_identity, 2) & 0o7777 != 0o700
                        )
                    ):
                        raise sealed_reader_error(
                            "trusted-time retained recovery directory is unavailable"
                        )
                directory_owner = _exact_tuple_getitem(directory_owners, -1)
                for index in _exact_range(_exact_len(artifact_components)):
                    parent_owner = _exact_tuple_getitem(directory_owners, index)
                    child_owner = _exact_tuple_getitem(directory_owners, index + 1)
                    if _native_owner_statat(
                        parent_owner,
                        _exact_tuple_getitem(artifact_components, index),
                    ) != _native_owner_fstat(child_owner):
                        raise sealed_reader_error("trusted-time retained recovery path changed")
                initial_inventory = sealed_inventory_snapshot(directory_owner)
                if initial_inventory is None:
                    raise sealed_reader_error(
                        "trusted-time retained recovery inventory is unavailable"
                    )
                names = _exact_tuple_getitem(initial_inventory, 0)
                outcome_names: tuple[str, ...] = ()
                for name in names:
                    if name == "trusted-time-post-enrollment-start-outcome.json" or (
                        _str_startswith(
                            name,
                            "trusted-time-post-enrollment-start-outcome-",
                        )
                        and _str_endswith(name, ".json")
                    ):
                        outcome_names += (name,)
                if (
                    outcome_names != (outcome_file_name,)
                    or ".post-enrollment-start-recovery-outcome-staging" in names
                ):
                    raise sealed_reader_error("trusted-time retained recovery inventory is invalid")
                slot_candidate = _native_open_regular(
                    directory_owner,
                    ".post-enrollment-start-controller-outcome-slot",
                )
                slot_owner = slot_candidate
                slot_candidate = None
                _native_owner_flock(slot_owner, _native_lock_shared_nonblocking)
                observed_slot = sealed_read_open_owner(slot_owner, 128 * 1_024)
                observed_outcome = sealed_read_regular(
                    directory_owner,
                    outcome_file_name,
                    128 * 1_024,
                )
                expected_slot = sealed_outcome_slot_bytes(
                    "phase6d-post-enrollment-start-retained-recovery-outcome-v1",
                    outcome_sha256,
                    "retained",
                )
                if (
                    observed_slot is None
                    or observed_outcome is None
                    or _exact_tuple_getitem(observed_slot, 0) != expected_slot
                    or _exact_tuple_getitem(observed_slot, 1) != _exact_tuple_getitem(before, 8)
                    or _native_owner_fstat(slot_owner) != _exact_tuple_getitem(observed_slot, 1)
                    or _native_owner_statat(
                        directory_owner,
                        ".post-enrollment-start-controller-outcome-slot",
                    )
                    != _exact_tuple_getitem(observed_slot, 1)
                    or _exact_tuple_getitem(observed_outcome, 0) != _exact_tuple_getitem(before, 6)
                    or _exact_tuple_getitem(observed_outcome, 1) != _exact_tuple_getitem(before, 7)
                    or _native_owner_statat(directory_owner, outcome_file_name)
                    != _exact_tuple_getitem(observed_outcome, 1)
                ):
                    raise sealed_reader_error(
                        "trusted-time retained recovery evidence is unavailable"
                    )
                _native_owner_fsync(directory_owner)
                final_inventory = sealed_inventory_snapshot(directory_owner)
                after = sealed_recovery_receipt_object_projection(receipt)
                roots_after = (
                    sealed_builtin_roots(artifact_directory, ignored_root)
                    if builtin_roots
                    else sealed_public_roots(artifact_directory, ignored_root)
                )
                for index in _exact_range(_exact_len(artifact_components)):
                    parent_owner = _exact_tuple_getitem(directory_owners, index)
                    child_owner = _exact_tuple_getitem(directory_owners, index + 1)
                    if _native_owner_statat(
                        parent_owner,
                        _exact_tuple_getitem(artifact_components, index),
                    ) != _native_owner_fstat(child_owner):
                        raise sealed_reader_error("trusted-time retained recovery path changed")
                if (
                    final_inventory != initial_inventory
                    or after != before
                    or roots_after != roots
                    or _native_owner_fstat(slot_owner) != _exact_tuple_getitem(observed_slot, 1)
                    or _native_owner_statat(
                        directory_owner,
                        ".post-enrollment-start-controller-outcome-slot",
                    )
                    != _exact_tuple_getitem(observed_slot, 1)
                    or _native_owner_statat(directory_owner, outcome_file_name)
                    != _exact_tuple_getitem(observed_outcome, 1)
                ):
                    raise sealed_reader_error("trusted-time retained recovery changed")
                durable = True
            except _base_exception_type as error:
                primary_error = error
        finally:
            try:
                finish_recovery_cleanup_once()
            finally:
                try:
                    if not cleanup_completed:
                        finish_recovery_cleanup_once()
                finally:
                    try:
                        if not cleanup_completed:
                            finish_recovery_cleanup_once()
                    finally:
                        if not cleanup_completed:
                            finish_recovery_cleanup_once()
            if not cleanup_completed and cleanup_error is None:
                cleanup_error = sealed_reader_error(
                    "trusted-time projection native owner cleanup is unavailable"
                )
        terminal = primary_error
        if terminal is None or (
            _exact_isinstance(terminal, _ordinary_exception_type)
            and cleanup_error is not None
            and not _exact_isinstance(cleanup_error, _ordinary_exception_type)
        ):
            terminal = cleanup_error
        if terminal is not None:
            if not _exact_isinstance(terminal, _ordinary_exception_type):
                raise terminal
            return None
        return before if durable else None

    def sealed_recovery_checkpoint_projection(
        checkpoint: object,
    ) -> tuple[object, ...] | None:
        if _exact_type(checkpoint) is not _recovery_checkpoint_type:
            return None
        try:
            values: tuple[object, ...] = ()
            for descriptor in _recovery_checkpoint_descriptors:
                values += (
                    sealed_descriptor_value(
                        descriptor,
                        checkpoint,
                        _recovery_checkpoint_type,
                    ),
                )
            retained_claim = _exact_tuple_getitem(values, 0)
            roots = sealed_public_roots(
                _exact_tuple_getitem(values, 1),
                _exact_tuple_getitem(values, 2),
            )
            started = _exact_tuple_getitem(values, 3)
            deadline = _exact_tuple_getitem(values, 4)
            observed = _exact_tuple_getitem(values, 5)
            if (
                _exact_type(retained_claim) is not sealed_retained_claim_type
                or roots is None
                or _exact_type(started) is not _exact_int_type
                or _exact_type(deadline) is not _exact_int_type
                or _exact_type(observed) is not _exact_int_type
                or started < 0
                or deadline <= started
                or observed < started
                or observed >= deadline
            ):
                return None
            return (
                _id(retained_claim),
                _exact_tuple_getitem(roots, 0),
                _exact_tuple_getitem(roots, 1),
                started,
                deadline,
                observed,
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None

    def sealed_controller_checkpoint_projection(
        checkpoint: object,
    ) -> tuple[object, ...] | None:
        if _exact_type(checkpoint) is not _controller_checkpoint_type:
            return None
        try:
            values: tuple[object, ...] = ()
            for descriptor in _controller_checkpoint_descriptors:
                values += (
                    sealed_descriptor_value(
                        descriptor,
                        checkpoint,
                        _controller_checkpoint_type,
                    ),
                )
            retained_claim = _exact_tuple_getitem(values, 0)
            outcome_kind = _exact_tuple_getitem(values, 1)
            roots = sealed_public_roots(
                _exact_tuple_getitem(values, 2),
                _exact_tuple_getitem(values, 3),
            )
            started = _exact_tuple_getitem(values, 4)
            action_deadline = _exact_tuple_getitem(values, 5)
            deadline = _exact_tuple_getitem(values, 6)
            observed = _exact_tuple_getitem(values, 7)
            if (
                _exact_type(retained_claim) is not sealed_retained_claim_type
                or _exact_type(outcome_kind) is not _exact_str_type
                or outcome_kind not in ("success", "failure")
                or roots is None
                or _exact_type(started) is not _exact_int_type
                or _exact_type(action_deadline) is not _exact_int_type
                or _exact_type(deadline) is not _exact_int_type
                or _exact_type(observed) is not _exact_int_type
                or started < 0
                or action_deadline <= started
                or deadline <= started
                or observed < started
                or observed >= deadline
                or (outcome_kind == "success" and deadline != action_deadline)
                or (outcome_kind == "failure" and deadline < action_deadline)
            ):
                return None
            return (
                _id(retained_claim),
                outcome_kind,
                _exact_tuple_getitem(roots, 0),
                _exact_tuple_getitem(roots, 1),
                started,
                action_deadline,
                deadline,
                observed,
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None

    def new_sealed_choreography_checkpoint(
        lease_sha256: str,
        started_monotonic_ns: int,
        deadline_monotonic_ns: int,
        observed_monotonic_ns: int,
    ) -> _ChoreographyCheckpoint:
        if (
            _exact_type(lease_sha256) is not _exact_str_type
            or _sha256_pattern.fullmatch(lease_sha256) is None
            or _exact_type(started_monotonic_ns) is not _exact_int_type
            or _exact_type(deadline_monotonic_ns) is not _exact_int_type
            or _exact_type(observed_monotonic_ns) is not _exact_int_type
            or started_monotonic_ns < 0
            or deadline_monotonic_ns <= started_monotonic_ns
            or observed_monotonic_ns < started_monotonic_ns
            or observed_monotonic_ns >= deadline_monotonic_ns
        ):
            raise sealed_reader_error("trusted-time choreography checkpoint is unavailable")
        checkpoint = _object_new(_choreography_checkpoint_type)
        values = (
            lease_sha256,
            started_monotonic_ns,
            deadline_monotonic_ns,
            observed_monotonic_ns,
        )
        for index in _exact_range(_exact_len(values)):
            _member_descriptor_set(
                _exact_tuple_getitem(_choreography_checkpoint_descriptors, index),
                checkpoint,
                _exact_tuple_getitem(values, index),
            )
        return checkpoint  # type: ignore[return-value]

