    def sealed_ascii_name(value: object, *, punctuation: str) -> bool:
        if _exact_type(value) is not _exact_str_type or not value or _exact_len(value) > 256:
            return False
        for index in _exact_range(_exact_len(value)):
            character = _exact_tuple_getitem(_exact_tuple(value), index)
            if not (
                "a" <= character <= "z"
                or "A" <= character <= "Z"
                or "0" <= character <= "9"
                or (index > 0 and character in punctuation)
            ):
                return False
        return True

    def sealed_daemon_identity(value: object) -> bool:
        if not sealed_object_has_keys(
            value,
            ("context_name", "daemon_id", "endpoint"),
        ):
            return False
        context_name = sealed_json_object_get(value, "context_name")
        daemon_id = sealed_json_object_get(value, "daemon_id")
        endpoint = sealed_json_object_get(value, "endpoint")
        if (
            (
                context_name != "<DOCKER_HOST>"
                and not sealed_ascii_name(context_name, punctuation="_.-")
            )
            or not sealed_ascii_name(daemon_id, punctuation=":._-")
            or _exact_type(endpoint) is not _exact_str_type
            or not endpoint
            or _exact_len(endpoint) > 4_096
            or not _str_startswith(endpoint, "unix:///")
            or "?" in endpoint  # type: ignore[operator]
            or "#" in endpoint  # type: ignore[operator]
            or "%" in endpoint  # type: ignore[operator]
        ):
            return False
        for character in endpoint:  # type: ignore[attr-defined]
            codepoint = _exact_ord(character)
            if codepoint < 32 or codepoint == 127:
                return False
        path = endpoint[7:]  # type: ignore[index]
        if not _str_startswith(path, "/") or _str_startswith(path, "//"):
            return False
        components = _str_split(path, "/")
        if _exact_type(components) is not _exact_list_type or not components:
            return False
        for index in _exact_range(1, _exact_len(components)):
            component = _exact_list_getitem(components, index)
            if not component or component in (".", ".."):
                return False
        return True

    def sealed_persistent_container_projection(
        value: object,
        expected_service: str,
    ) -> tuple[str, str] | None:
        fields = (
            "container_id",
            "image_configuration_projection_sha256",
            "image_id",
            "running_state_projection_sha256",
            "service",
            "stable_inspection_projection_sha256",
        )
        if not sealed_object_has_keys(value, fields):
            return None
        container_id = sealed_json_object_get(value, "container_id")
        image_id = sealed_json_object_get(value, "image_id")
        if (
            sealed_json_object_get(value, "service") != expected_service
            or not sealed_sha256_text(container_id)
            or _exact_type(image_id) is not _exact_str_type
            or not _str_startswith(image_id, "sha256:")
            or not sealed_sha256_text(image_id[7:])  # type: ignore[index]
            or not sealed_object_sha_fields(
                value,
                (
                    "image_configuration_projection_sha256",
                    "running_state_projection_sha256",
                    "stable_inspection_projection_sha256",
                ),
            )
        ):
            return None
        return container_id, image_id  # type: ignore[return-value]

    def sealed_persistent_topology_projection(
        encoded: object,
    ) -> tuple[object, ...] | None:
        try:
            payload = decode_canonical_json_object(encoded, maximum_bytes=64 * 1_024)
            fields = (
                authority_field_names
                + persistent_topology_closed_field_names
                + persistent_topology_field_names
            )
            operation_id = sealed_json_object_get(payload, "operation_id")
            approval_sha256 = sealed_json_object_get(payload, "approval_sha256")
            claim_sha256 = sealed_json_object_get(payload, "claim_sha256")
            retained_claim_sha256 = sealed_json_object_get(
                payload,
                "retained_claim_artifact_sha256",
            )
            admission_sha256 = sealed_json_object_get(
                payload,
                "active_controller_admission_sha256",
            )
            successor_sha256 = sealed_json_object_get(payload, "successor_candidate_sha256")
            digest_fields = (
                "active_controller_admission_sha256",
                "approval_sha256",
                "claim_sha256",
                "created_topology_snapshot_sha256",
                "database_secret_consumed_candidate_sha256",
                "final_action_snapshot_sha256",
                "final_action_stable_topology_sha256",
                "network_id",
                "network_projection_sha256",
                "release_marker_candidate_sha256",
                "release_staging_absence_candidate_sha256",
                "retained_claim_artifact_sha256",
                "staged_input_retirement_candidate_sha256",
                "successor_candidate_sha256",
            )
            approved_launch = sealed_json_object_get(payload, "approved_launch")
            source = sealed_persistent_container_projection(
                sealed_json_object_get(payload, "source_container"),
                "chrony-nts",
            )
            supervisor = sealed_persistent_container_projection(
                sealed_json_object_get(payload, "supervisor_container"),
                "trusted-time-supervisor",
            )
            volumes = sealed_json_object_get(payload, "volume_identities")
            if (
                not sealed_object_has_keys(payload, fields)
                or not sealed_false_fields(payload, authority_field_names)
                or not sealed_false_fields(payload, persistent_topology_closed_field_names)
                or sealed_json_object_get(payload, "contract_version")
                != "phase6d-post-enrollment-start-persistent-topology-snapshot-v1"
                or sealed_json_object_get(payload, "status")
                != "persistent_topology_snapshot_unqualified"
                or sealed_json_object_get(payload, "service")
                != "trusted-time-post-enrollment-start"
                or sealed_json_object_get(payload, "compose_project")
                != "autoquanttrader-trusted-time"
                or sealed_json_object_get(payload, "submitted_project_container_count") != 2
                or not sealed_uuid4_text(operation_id)
                or not sealed_object_sha_fields(payload, digest_fields)
                or not sealed_launch_projection(approved_launch)
                or not sealed_daemon_identity(sealed_json_object_get(payload, "daemon_identity"))
                or not sealed_object_has_keys(volumes, ("socket_sha256", "state_sha256"))
                or not sealed_object_sha_fields(volumes, ("socket_sha256", "state_sha256"))
                or source is None
                or supervisor is None
                or _exact_tuple_getitem(source, 0) == _exact_tuple_getitem(supervisor, 0)
                or _exact_tuple_getitem(source, 1)
                != sealed_json_object_get(approved_launch, "source_image_id")
                or _exact_tuple_getitem(supervisor, 1)
                != sealed_json_object_get(approved_launch, "supervisor_image_id")
                or _exact_tuple_getitem(source, 1) == _exact_tuple_getitem(supervisor, 1)
            ):
                return None
            return (
                payload,
                operation_id,
                approval_sha256,
                claim_sha256,
                retained_claim_sha256,
                admission_sha256,
                successor_sha256,
                _exact_tuple_getitem(source, 1),
                _exact_tuple_getitem(supervisor, 1),
                sealed_json_object_get(approved_launch, "git_revision"),
                sealed_json_object_get(approved_launch, "image_admission_sha256"),
            )
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None

