    def sealed_shutdown_locator_payload_projection(
        payload: object,
    ) -> tuple[object, ...] | None:
        fields = (
            authority_field_names
            + shutdown_locator_closed_field_names
            + (
                "active_controller_session_sha256",
                "contract_version",
                "network_name",
                "persistent_topology",
                "persistent_topology_sha256",
                "persistent_topology_transcript_sha256",
                "service",
                "socket_volume_name",
                "state_volume_name",
                "status",
            )
        )
        if (
            not sealed_object_has_keys(payload, fields)
            or not sealed_false_fields(payload, authority_field_names)
            or not sealed_false_fields(payload, shutdown_locator_closed_field_names)
            or sealed_json_object_get(payload, "contract_version")
            != "phase6d-post-enrollment-start-durable-shutdown-locator-v1"
            or sealed_json_object_get(payload, "service") != "trusted-time-post-enrollment-start"
            or sealed_json_object_get(payload, "status") != "durable_shutdown_locator_unqualified"
        ):
            return None
        session_sha256 = sealed_json_object_get(
            payload,
            "active_controller_session_sha256",
        )
        network_name = sealed_json_object_get(payload, "network_name")
        persistent_payload = sealed_json_object_get(payload, "persistent_topology")
        persistent_encoded = sealed_json_object_bytes(persistent_payload)
        persistent = sealed_persistent_topology_projection(persistent_encoded)
        persistent_sha256 = sealed_json_object_get(payload, "persistent_topology_sha256")
        transcript_sha256 = sealed_json_object_get(
            payload,
            "persistent_topology_transcript_sha256",
        )
        if not sealed_sha256_text(session_sha256):
            return None
        network_material = (
            "trusted-time-sealed-json-object-v1",
            (
                (
                    "contract_version",
                    "phase6d-post-enrollment-start-created-topology-network-name-v1",
                ),
                ("session_sha256", session_sha256),
            ),
        )
        expected_network_sha256 = sealed_sha256_bytes(sealed_json_object_bytes(network_material))
        encoded = sealed_json_object_bytes(payload)
        if (
            expected_network_sha256 is None
            or network_name
            != "autoquanttrader-trusted-time-post-enrollment-" + expected_network_sha256
            or sealed_json_object_get(payload, "socket_volume_name")
            != "autoquanttrader-trusted-time_chrony_command_socket"
            or sealed_json_object_get(payload, "state_volume_name")
            != "autoquanttrader-trusted-time_chrony_state"
            or persistent is None
            or not sealed_sha256_text(persistent_sha256)
            or sealed_sha256_bytes(persistent_encoded) != persistent_sha256
            or not sealed_sha256_text(transcript_sha256)
            or _exact_tuple_getitem(persistent, 0) is not persistent_payload
            or not encoded
            or _exact_len(encoded) > 64 * 1_024
        ):
            return None
        locator_sha256 = sealed_sha256_bytes(encoded)
        if locator_sha256 is None:
            return None
        return (
            encoded,
            locator_sha256,
            persistent_sha256,
            transcript_sha256,
            (
                _exact_tuple_getitem(persistent, 1),
                _exact_tuple_getitem(persistent, 2),
                _exact_tuple_getitem(persistent, 3),
                _exact_tuple_getitem(persistent, 4),
                _exact_tuple_getitem(persistent, 5),
                _exact_tuple_getitem(persistent, 6),
                _exact_tuple_getitem(persistent, 7),
                _exact_tuple_getitem(persistent, 8),
                _exact_tuple_getitem(persistent, 9),
                _exact_tuple_getitem(persistent, 10),
            ),
        )

    def sealed_shutdown_locator_object_projection(
        locator: object,
    ) -> tuple[object, ...] | None:
        if (
            not controller_projection_types_finalized
            or shutdown_locator_projection_type is None
            or shutdown_locator_projection_descriptors is None
            or _exact_type(locator) is not shutdown_locator_projection_type
        ):
            return None
        try:
            values: tuple[object, ...] = ()
            for descriptor in shutdown_locator_projection_descriptors:
                values += (
                    sealed_descriptor_value(
                        descriptor,
                        locator,
                        shutdown_locator_projection_type,
                    ),
                )
            persistent_encoded = _exact_tuple_getitem(values, 6)
            persistent = sealed_persistent_topology_projection(persistent_encoded)
            if persistent is None:
                return None
            payload_items: tuple[tuple[str, object], ...] = ()
            for field_name in authority_field_names:
                payload_items += ((field_name, False),)
            for field_name in shutdown_locator_closed_field_names:
                payload_items += ((field_name, False),)
            payload_items += (
                (
                    "active_controller_session_sha256",
                    _exact_tuple_getitem(values, 0),
                ),
                (
                    "contract_version",
                    "phase6d-post-enrollment-start-durable-shutdown-locator-v1",
                ),
                ("network_name", _exact_tuple_getitem(values, 1)),
                ("persistent_topology", _exact_tuple_getitem(persistent, 0)),
                ("persistent_topology_sha256", _exact_tuple_getitem(values, 4)),
                (
                    "persistent_topology_transcript_sha256",
                    _exact_tuple_getitem(values, 5),
                ),
                ("service", "trusted-time-post-enrollment-start"),
                ("socket_volume_name", _exact_tuple_getitem(values, 2)),
                ("state_volume_name", _exact_tuple_getitem(values, 3)),
                ("status", "durable_shutdown_locator_unqualified"),
            )
            payload = (
                "trusted-time-sealed-json-object-v1",
                _exact_tuple(_exact_sorted(payload_items)),
            )
            return sealed_shutdown_locator_payload_projection(payload)
        except _base_exception_type as error:
            if not _exact_isinstance(error, _ordinary_exception_type):
                raise
            return None

