    def exact_parent_path_string(candidate: object) -> str | None:
        if (
            _exact_type(candidate) is not _exact_str_type
            or not _str_startswith(candidate, "/")
            or _str_endswith(candidate, "/")
            or _str_find(candidate, "\x00") >= 0
        ):
            return None
        separator = _str_rfind(candidate, "/")
        if separator < 0:
            return None
        return "/" if separator == 0 else _str_getitem(candidate, _exact_slice(None, separator))

