def _run_under_authenticated_issuer_lifecycle_lock[LifecycleResult](
    owner: object,
    operation: Callable[[], LifecycleResult],
    /,
    *,
    _bound_lifecycle_lock: Callable[[object], object] = (
        _bound_authenticated_issuer_lifecycle_lock
    ),
    _run_under_lock: Callable[[object, Callable[[], LifecycleResult]], LifecycleResult] = (
        _run_under_exact_rlock
    ),
) -> LifecycleResult:
    """Run one non-I/O issuer transition under its closure-bound exact mutex."""

    lifecycle_lock = _bound_lifecycle_lock(owner)
    return _run_under_lock(lifecycle_lock, operation)


class _DuplicateJsonKey(ValueError):
    pass


class _BoundedRunner(Protocol):
    def __call__(
        self,
        argv: tuple[str, ...],
        *,
        cwd: Path,
        environment: Mapping[str, str] | tuple[tuple[str, str], ...],
        timeout_seconds: float,
        maximum_stdout_bytes: int,
        maximum_stderr_bytes: int,
        stdin_bytes: bytes | None = None,
        maximum_stdin_bytes: int = 0,
    ) -> BoundedSubprocessResult: ...


def _require_exact_bounded_runner_result(
    value: object,
    *,
    expected_argv: tuple[str, ...],
    maximum_stdout_bytes: int,
    maximum_stderr_bytes: int,
    require_argv_identity: bool = False,
) -> BoundedSubprocessResult:
    """Require the runner's exact immutable four-slot result authority."""

    if type(value) is not tuple or len(value) != 4:
        raise ValueError
    result_argv = tuple.__getitem__(value, 0)
    returncode = tuple.__getitem__(value, 1)
    stdout = tuple.__getitem__(value, 2)
    stderr = tuple.__getitem__(value, 3)
    if (
        type(expected_argv) is not tuple
        or not expected_argv
        or any(type(argument) is not str or not argument for argument in expected_argv)
        or type(require_argv_identity) is not bool
        or (require_argv_identity and result_argv is not expected_argv)
        or type(result_argv) is not tuple
        or len(result_argv) != len(expected_argv)
        or any(type(argument) is not str or not argument for argument in result_argv)
        or result_argv != expected_argv
        or type(returncode) is not int
        or type(stdout) is not bytes
        or type(stderr) is not bytes
        or type(maximum_stdout_bytes) is not int
        or maximum_stdout_bytes < 0
        or len(stdout) > maximum_stdout_bytes
        or type(maximum_stderr_bytes) is not int
        or maximum_stderr_bytes < 0
        or len(stderr) > maximum_stderr_bytes
    ):
        raise ValueError
    return cast(BoundedSubprocessResult, value)


def _unique_json_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise _DuplicateJsonKey
        result[key] = value
    return result


def _bounded_json_integer(token: str) -> int:
    if len(token) > 80:
        raise ValueError
    value = int(token)
    if value.bit_length() > _MAXIMUM_JSON_INTEGER_BITS:
        raise ValueError
    return value


def _require_bounded_json_tree(root: object) -> None:
    remaining = _MAXIMUM_JSON_NODES
    stack: list[tuple[object, int]] = [(root, 0)]
    while stack:
        value, depth = stack.pop()
        remaining -= 1
        if remaining < 0 or depth > _MAXIMUM_JSON_DEPTH:
            raise ValueError
        if value is None or type(value) in {bool, str}:
            if type(value) is str and any(
                0xD800 <= ord(character) <= 0xDFFF for character in value
            ):
                raise ValueError
            continue
        if type(value) is int:
            if value.bit_length() > _MAXIMUM_JSON_INTEGER_BITS:
                raise ValueError
            continue
        if type(value) is list:
            items = cast(list[object], value)
            if len(items) > remaining:
                raise ValueError
            stack.extend((item, depth + 1) for item in reversed(items))
            continue
        if type(value) is dict:
            mapping = cast(dict[object, object], value)
            if 2 * len(mapping) > remaining:
                raise ValueError
            for key, item in reversed(tuple(mapping.items())):
                if type(key) is not str:
                    raise ValueError
                stack.append((item, depth + 1))
                stack.append((key, depth + 1))
            continue
        raise ValueError


def _contains_unquoted_json_whitespace(raw: bytes) -> bool:
    in_string = False
    escaped = False
    for byte in raw:
        if in_string:
            if escaped:
                escaped = False
            elif byte == 0x5C:
                escaped = True
            elif byte == 0x22:
                in_string = False
        elif byte == 0x22:
            in_string = True
        elif byte in {0x09, 0x0A, 0x0D, 0x20}:
            return True
    return False


def _decode_strict_json[JsonRoot: (dict[str, object], list[object], str)](
    raw: bytes,
    *,
    expected_type: type[JsonRoot],
    maximum_bytes: int,
) -> JsonRoot:
    """Decode one bounded unique-key JSON value from raw Docker bytes."""

    if type(raw) is not bytes:
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation is unavailable"
        )
    framed = raw[:-1] if raw.endswith(b"\n") else raw
    if (
        not raw
        or type(maximum_bytes) is not int
        or maximum_bytes <= 0
        or len(raw) > maximum_bytes
        or b"\0" in raw
        or b"\r" in raw
        or raw.startswith(b"\xef\xbb\xbf")
        or not framed
        or framed[:1] in b" \t\n\r"
        or framed[-1:] in b" \t\n\r"
        or _contains_unquoted_json_whitespace(framed)
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation is unavailable"
        )
    try:
        decoded: Any = json.loads(
            raw.decode("utf-8", errors="strict"),
            object_pairs_hook=_unique_json_object,
            parse_constant=lambda _: (_ for _ in ()).throw(ValueError()),
            parse_int=_bounded_json_integer,
            parse_float=lambda _: (_ for _ in ()).throw(ValueError()),
        )
        _require_bounded_json_tree(decoded)
    except (
        _DuplicateJsonKey,
        json.JSONDecodeError,
        RecursionError,
        TypeError,
        UnicodeError,
        ValueError,
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation is unavailable"
        ) from None
    if type(decoded) is not expected_type:
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation is unavailable"
        )
    return decoded


def _canonical_sha256(payload: object) -> str:
    return hashlib.sha256(canonical_first_enrollment_json_bytes(payload)).hexdigest()


_ReadReceipt = tuple[str, int, str, tuple[str, ...], int, int, str]
_ReadReceipts = tuple[_ReadReceipt, ...]


def _require_read_receipt(
    value: object,
    *,
    expected_ordinal: int,
    _sha256_pattern: re.Pattern[str] = _SHA256_PATTERN,
) -> _ReadReceipt:
    if (
        type(value) is not tuple
        or len(value) != 7
        or tuple.__getitem__(value, 0) != "trusted-time-read-receipt-v1"
        or type(tuple.__getitem__(value, 1)) is not int
        or tuple.__getitem__(value, 1) != expected_ordinal
        or type(tuple.__getitem__(value, 2)) is not str
        or not tuple.__getitem__(value, 2)
        or type(tuple.__getitem__(value, 3)) is not tuple
        or not tuple.__getitem__(value, 3)
        or any(
            type(argument) is not str or not argument for argument in tuple.__getitem__(value, 3)
        )
        or type(tuple.__getitem__(value, 4)) is not int
        or tuple.__getitem__(value, 4) < 0
        or type(tuple.__getitem__(value, 5)) is not int
        or not 0 <= tuple.__getitem__(value, 5) <= tuple.__getitem__(value, 4)
        or type(tuple.__getitem__(value, 6)) is not str
        or _sha256_pattern.fullmatch(tuple.__getitem__(value, 6)) is None
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation receipt is unavailable"
        )
    return cast(_ReadReceipt, value)


def _read_receipt_immutable_json(
    value: object,
    *,
    expected_ordinal: int,
    _require_receipt: Callable[..., _ReadReceipt] = _require_read_receipt,
) -> object:
    receipt = _require_receipt(value, expected_ordinal=expected_ordinal)
    return (
        0,
        (
            ("argv", (1, tuple.__getitem__(receipt, 3))),
            ("label", tuple.__getitem__(receipt, 2)),
            ("maximum_stdout_bytes", tuple.__getitem__(receipt, 4)),
            ("ordinal", tuple.__getitem__(receipt, 1)),
            ("stdout_sha256", tuple.__getitem__(receipt, 6)),
            ("stdout_size", tuple.__getitem__(receipt, 5)),
            ("timeout_milliseconds", 2_000),
        ),
    )


