_CANONICAL_UINT_PATTERN = rb"(?:0|[1-9][0-9]{0,77})"


def _fixed_marker_pattern(*, path: bytes, sha256_pattern: bytes, size_pattern: bytes) -> bytes:
    return b"".join(
        (
            rb'{"byte_sha256":"(',
            sha256_pattern,
            rb')","changed_time_ns":(',
            _CANONICAL_UINT_PATTERN,
            rb'),"device":(',
            _CANONICAL_UINT_PATTERN,
            rb'),"inode":(',
            _CANONICAL_UINT_PATTERN,
            rb'),"link_count":1,"mode":256,"modified_time_ns":(',
            _CANONICAL_UINT_PATTERN,
            rb'),"owner_gid":10001,"owner_uid":10001,"path":"',
            path,
            rb'","regular":true,"size":(',
            size_pattern,
            rb")}",
        )
    )


