def _minimal_docker_environment(
    submitted: Mapping[str, str],
    *,
    endpoint: str,
    _admitted_input_keys: tuple[str, ...] = (
        "LANG",
        "LC_ALL",
        "NO_COLOR",
        "PATH",
        "TERM",
        "TMPDIR",
    ),
    _fixed_path: str = "/usr/bin:/bin",
) -> tuple[tuple[str, str], ...]:
    if (
        type(submitted) is not dict
        or type(endpoint) is not str
        or type(_fixed_path) is not str
        or _fixed_path != "/usr/bin:/bin"
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation environment is invalid"
        )
    try:
        selected = tuple(submitted.items())
    except (RuntimeError, TypeError, ValueError):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation environment is invalid"
        ) from None
    if (
        any(
            type(item) is not tuple
            or len(item) != 2
            or type(tuple.__getitem__(item, 0)) is not str
            or type(tuple.__getitem__(item, 1)) is not str
            or not tuple.__getitem__(item, 0)
            or "=" in tuple.__getitem__(item, 0)
            or "\0" in tuple.__getitem__(item, 0)
            or "\0" in tuple.__getitem__(item, 1)
            for item in selected
        )
        or any(tuple.__getitem__(item, 0) not in _admitted_input_keys for item in selected)
        or len(selected) != len(frozenset(tuple.__getitem__(item, 0) for item in selected))
        or not endpoint
        or "\0" in endpoint
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation environment is invalid"
        )

    def selected_pair(key: str) -> tuple[tuple[str, str], ...]:
        matches = tuple(item for item in selected if tuple.__getitem__(item, 0) == key)
        if not matches or key == "PATH":
            return ()
        return cast(tuple[tuple[str, str], ...], matches)

    return (
        ("DOCKER_HOST", endpoint),
        *selected_pair("LANG"),
        *selected_pair("LC_ALL"),
        *selected_pair("NO_COLOR"),
        ("PATH", _fixed_path),
        *selected_pair("TERM"),
        *selected_pair("TMPDIR"),
    )


def _docker_executable_identity(
    path: str,
    *,
    _stat: Callable[..., os.stat_result] = os.stat,
    _access: Callable[..., bool] = os.access,
    _is_absolute: Callable[[str], bool] = os.path.isabs,
    _absolute: Callable[[str], str] = os.path.abspath,
    _normalize: Callable[[str], str] = os.path.normpath,
    _effective_uid: Callable[[], int] = os.geteuid,
    _is_regular: Callable[[int], bool] = stat.S_ISREG,
    _mode: Callable[[int], int] = stat.S_IMODE,
) -> tuple[int, ...]:
    try:
        metadata = _stat(path, follow_symlinks=False)
    except OSError:
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker executable is unavailable"
        ) from None
    if (
        type(path) is not str
        or not _is_absolute(path)
        or _absolute(path) != path
        or _normalize(path) != path
        or not _is_regular(metadata.st_mode)
        or metadata.st_uid not in {0, _effective_uid()}
        or _mode(metadata.st_mode) & 0o022
        or _mode(metadata.st_mode) & 0o111 == 0
        or metadata.st_nlink != 1
        or not _access(path, os.X_OK, effective_ids=True)
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker executable is unavailable"
        )
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
        metadata.st_nlink,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


def _resolve_trusted_docker_executable(
    *,
    _candidates: tuple[str, ...] = (
        "/Applications/Docker.app/Contents/Resources/bin/docker",
        "/opt/homebrew/bin/docker",
        "/usr/local/bin/docker",
        "/usr/bin/docker",
    ),
    _realpath: Callable[..., str] = os.path.realpath,
    _normpath: Callable[[str], str] = os.path.normpath,
    _identity: Callable[[str], tuple[int, ...]] = _docker_executable_identity,
) -> tuple[str, tuple[int, ...]]:
    for candidate in _candidates:
        try:
            if type(candidate) is not str or not candidate.startswith("/"):
                raise ValueError
            resolved_path = _realpath(candidate, strict=True)
            if (
                type(resolved_path) is not str
                or not resolved_path.startswith("/")
                or _normpath(resolved_path) != resolved_path
            ):
                raise ValueError
            identity = _identity(resolved_path)
        except (OSError, TrustedTimePostEnrollmentTopologyReaderError, ValueError):
            continue
        return resolved_path, identity
    raise TrustedTimePostEnrollmentTopologyReaderError(
        "trusted-time Docker executable is unavailable"
    )


def _socket_path(identity: _DaemonIdentityRegistration) -> str:
    exact = _require_daemon_identity_registration(identity)
    return tuple.__getitem__(exact, 2)[7:]


def _socket_identity(
    path: str,
    *,
    _stat: Callable[..., os.stat_result] = os.stat,
    _effective_uid: Callable[[], int] = os.geteuid,
    _is_socket: Callable[[int], bool] = stat.S_ISSOCK,
    _mode: Callable[[int], int] = stat.S_IMODE,
) -> tuple[int, int, int, int, int]:
    try:
        metadata = _stat(path, follow_symlinks=False)
    except OSError:
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation session is unavailable"
        ) from None
    if (
        type(path) is not str
        or not path.startswith("/")
        or not _is_socket(metadata.st_mode)
        or metadata.st_uid not in {0, _effective_uid()}
        or _mode(metadata.st_mode) & 0o002
    ):
        raise TrustedTimePostEnrollmentTopologyReaderError(
            "trusted-time Docker observation session is unavailable"
        )
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
    )


