    def _recovery_outcome_retention_is_armed(
        self,
        choreography_lease: object,
        recovery_retention_capability: object,
        *,
        artifact_directory: Path,
        ignored_root: Path,
        _fspath: Callable[[os.PathLike[str]], str] = os.fspath,
        _run_lifecycle: Callable[[object, Callable[[], Any]], Any] = (
            _run_under_authenticated_issuer_lifecycle_lock
        ),
    ) -> bool:
        """Read one exact recovery state without changing or poisoning it."""

        try:
            launch_lock_binding = self._validate_lock()
            ignored_root_value = tuple.__getitem__(launch_lock_binding, 2)
            artifact_directory_value = tuple.__getitem__(launch_lock_binding, 3)
            if (
                type(artifact_directory) is not type(Path())
                or type(ignored_root) is not type(Path())
                or _fspath(artifact_directory) != artifact_directory_value
                or _fspath(ignored_root) != ignored_root_value
            ):
                raise TrustedTimePostEnrollmentTopologyReaderError(
                    "trusted-time recovery retention state is unavailable"
                )

            observed_scope_nonce: object | None = None

            def require_retention_read_heap_locked() -> None:
                nonlocal observed_scope_nonce
                if (
                    type(self._owner_pid) is not int
                    or self._owner_pid != os.getpid()
                    or self._closed
                    or self._busy
                    or not self._choreography_inflight
                    or self._choreography_scope_nonce is None
                ):
                    raise TrustedTimePostEnrollmentTopologyReaderError(
                        "trusted-time recovery retention state is unavailable"
                    )
                observed_scope_nonce = self._choreography_scope_nonce

            _run_lifecycle(self, require_retention_read_heap_locked)
            observed = self._monotonic_ns()
            if (
                type(observed) is not int
                or observed < 0
                or observed > _MAXIMUM_MONOTONIC_NANOSECONDS
            ):
                raise TrustedTimePostEnrollmentTopologyReaderError(
                    "trusted-time recovery retention state is unavailable"
                )
            first = _authenticated_recovery_outcome_retention_is_armed(
                self,
                choreography_lease,
                recovery_retention_capability,
                scope_nonce=observed_scope_nonce,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
                observed_monotonic_ns=observed,
            )
            if self._validate_lock() is not launch_lock_binding:
                raise TrustedTimePostEnrollmentTopologyReaderError(
                    "trusted-time recovery retention state is unavailable"
                )
            _run_lifecycle(self, require_retention_read_heap_locked)
            confirmed = _authenticated_recovery_outcome_retention_is_armed(
                self,
                choreography_lease,
                recovery_retention_capability,
                scope_nonce=observed_scope_nonce,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
                observed_monotonic_ns=observed,
            )
            if first is not confirmed:
                raise TrustedTimePostEnrollmentTopologyReaderError(
                    "trusted-time recovery retention state is unavailable"
                )
            return confirmed
        except Exception:
            raise TrustedTimePostEnrollmentTopologyReaderError(
                "trusted-time recovery retention state is unavailable"
            ) from None

